foreach ( array( 'dashboard/dashboard-data.php', 'dashboard/profile-completion.php', 'dashboard/dashboard-preferences.php', 'dashboard/dashboard-permissions.php', 'notifications/notification-service.php', 'notifications/notification-actions.php', 'notifications/notification-preferences.php', 'notifications/notification-permissions.php', 'api/dashboard-api.php', 'api/notifications-api.php' ) as $file ) { require_once SD_CORE_DIR . 'includes/' . $file; }
foreach ( array( 'database/schema.php', 'database/migrations.php', 'moderation/reports.php', 'moderation/report-workflow.php', 'moderation/content-actions.php', 'moderation/group-moderation.php', 'moderation/restrictions.php', 'blocking/blocking-service.php', 'blocking/blocking-enforcement.php', 'blocking/blocking-permissions.php', 'privacy/privacy-settings.php', 'privacy/personal-data-export.php', 'privacy/personal-data-erasure.php', 'audit/audit-logger.php', 'audit/audit-viewer.php', 'admin/admin-menu.php', 'admin/overview.php', 'admin/member-management.php', 'admin/moderation-queue.php', 'admin/safety-settings.php', 'admin/audit-pages.php', 'api/reports-api.php', 'api/moderation-api.php', 'api/blocking-api.php' ) as $file ) { require_once SD_CORE_DIR . 'includes/' . $file; }

function sd_core_enqueue_assets() { if ( ! is_admin() ) { wp_enqueue_style( 'sd-core', SD_CORE_URL . 'assets/core.css', array(), SD_CORE_VERSION ); } }
add_action( 'wp_enqueue_scripts', 'sd_core_enqueue_assets' );
function sd_core_admin_assets( $hook ) { if ( false !== strpos( $hook, 'sd-' ) ) { wp_enqueue_style( 'sd-core-admin', SD_CORE_URL . 'assets/css/admin.css', array(), SD_CORE_VERSION ); wp_enqueue_script( 'sd-core-admin', SD_CORE_URL . 'assets/js/admin.js', array(), SD_CORE_VERSION, true ); } }
add_action( 'admin_enqueue_scripts', 'sd_core_admin_assets' );
function sd_core_register_api_routes() { register_rest_route( 'social-discovery/v1', '/activity', array( 'methods' => 'POST', 'callback' => 'sd_core_api_activity_create', 'permission_callback' => 'sd_core_rest_permission' ) ); register_rest_route( 'social-discovery/v1', '/activity/comment', array( 'methods' => 'POST', 'callback' => 'sd_core_api_activity_comment', 'permission_callback' => 'sd_core_rest_permission' ) ); register_rest_route( 'social-discovery/v1', '/activity/favorite', array( 'methods' => 'POST', 'callback' => 'sd_core_api_activity_favorite', 'permission_callback' => 'sd_core_rest_permission' ) ); register_rest_route( 'social-discovery/v1', '/activity/save', array( 'methods' => 'POST', 'callback' => 'sd_core_api_save_activity', 'permission_callback' => 'sd_core_rest_permission' ) ); register_rest_route( 'social-discovery/v1', '/connections', array( 'methods' => 'POST', 'callback' => 'sd_core_api_connection', 'permission_callback' => 'sd_core_rest_permission' ) ); register_rest_route( 'social-discovery/v1', '/recommendations', array( 'methods' => 'GET', 'callback' => 'sd_core_api_recommendations', 'permission_callback' => 'sd_core_rest_permission' ) ); register_rest_route( 'social-discovery/v1', '/groups/create', array( 'methods' => 'POST', 'callback' => 'sd_core_api_group_create', 'permission_callback' => 'sd_core_rest_permission' ) ); register_rest_route( 'social-discovery/v1', '/groups/membership', array( 'methods' => 'POST', 'callback' => 'sd_core_api_group_membership', 'permission_callback' => 'sd_core_rest_permission' ) ); register_rest_route( 'social-discovery/v1', '/messages/send', array( 'methods' => 'POST', 'callback' => 'sd_core_api_message_send', 'permission_callback' => 'sd_core_rest_permission' ) ); register_rest_route( 'social-discovery/v1', '/messages/state', array( 'methods' => 'POST', 'callback' => 'sd_core_api_message_state', 'permission_callback' => 'sd_core_rest_permission' ) ); register_rest_route( 'social-discovery/v1', '/dashboard', array( 'methods' => 'GET', 'callback' => 'sd_core_api_dashboard', 'permission_callback' => 'sd_core_rest_permission' ) ); register_rest_route( 'social-discovery/v1', '/notifications/state', array( 'methods' => 'POST', 'callback' => 'sd_core_api_notification_state', 'permission_callback' => 'sd_core_rest_permission' ) ); register_rest_route( 'social-discovery/v1', '/reports', array( 'methods' => 'POST', 'callback' => 'sd_core_api_create_report', 'permission_callback' => 'sd_core_rest_permission' ) ); register_rest_route( 'social-discovery/v1', '/reports/status', array( 'methods' => 'POST', 'callback' => 'sd_core_api_report_update', 'permission_callback' => 'sd_core_rest_permission' ) ); register_rest_route( 'social-discovery/v1', '/blocks', array( 'methods' => 'POST', 'callback' => 'sd_core_api_block', 'permission_callback' => 'sd_core_rest_permission' ) ); }
add_action( 'rest_api_init', 'sd_core_register_api_routes' );
function sd_core_activate() { if ( ! get_role( 'sd_moderator' ) ) { add_role( 'sd_moderator', __( 'Community Moderator', 'social-discovery-core' ), array( 'read' => true ) ); } sd_core_register_capabilities(); sd_core_install_schema(); }
register_activation_hook( __FILE__, 'sd_core_activate' );
